tafsir_text:
وقوله :  {  وَأَرْجُلَكُمْ .  .  .  }

مردودة على الوجوه .  قال الفراء :  وحدَّثني قيس بن الربيع عن عاصم عن زِرّ عن عبد الله بن مسعود أنه قرأ ( وأرجلكم ) مقدّم ومؤخر .  قال الفراء :  وحدّثني محمد بن أبان القريشي عن أبى إسحاق الهَمْدانىّ عن رجل عن على أنه قال :  نزل الكتاب بالمسح ،  والسُنَّة الغَسْل .  قال الفراء :  وحدّثني أبو شهاب عن رجل عن الشعبيّ قال :  نزل جبريل صلى الله عليه وسلم بالمسح على محمد صلى الله عليهما وعلى جميع الأنبياء .  قال الفراء :  السنة الغسل .

وقوله :  {  أَوْ جَاء أَحَدٌ مِّنْكُمْ مِّنَ الْغَائطِ } كناية عن خلوة الرجل إذا أراد الحاجة .

وقوله :  {  فَاذْهَبْ أَنتَ وَرَبُّكَ فَقَاتِلا .  .  .  }

فقال ( أنت ) ولو ألقيت ( أنت ) فقيل :  اذهب وربك فقاتِلا كان صوابا ؛  لأنه في إحدى القراءتين {  إِنه يراكم وقبِيلُه } بغير ( هو ) وهي بهو و{  اذهب أنت وربك } أكثر في كلام العرب .  وذلك أنّ المردود على الاسم المرفوع إذا أضمر يكره ؛  لأن المرفوع خفي في الفعل ،  وليس كالمنصوب ؛  لأنّ المنصوب يظهر ؛  فتقول ضربته وضربتك ،  وتقول في المرفوع :  قام وقاما ،  فلا ترى اسما منفصلا في الأصل من الفعل ،  فلذلك أُوثِر إظهاره ،  وقد قال الله تبارك وتعالى {  أئذا كُنا تُرَاباً وَآبَاؤُنا } ولم يقل( نحن ) وكلّ صواب .

وإذا فرقت بين الاسم المعطوف بشيء قد وقع عليه الفعل حسن بعضَ الحسن .  من ذلك قولك :  ضربت زيدا وأنت .  ولو لم يكن زيد لقلت :  قمت أنا وأنت ،  وقمت وأنت قليل .  ولو كانت ( إِنا ها هنا قاعدين ) كان صوابا .

وقوله :  {  مِنْ أَجْلِ ذلك .  .  .  }

جواب لقتل ابن آدم صاحبه .

وقوله :  {  وَمَنْ أَحْيَاها } يقول :  عفا عنها ،  والإحياء ها هنا العفو .

وقوله :  {  وَكَتَبْنا عَلَيْهِمْ فِيها أَنَّ النَّفْسَ بِالنَّفْسِ .  .  .  }

تنصب ( النفس ) بوقوع ( أَنّ ) عليها .  وأنت في قوله {  وَالْعَيْنَ بِالْعَيْنِ وَالأَنْفَ بِالأَنْفِ } إلى قوله {  وَالْجُرُوحَ قِصَاصٌ } بالخيار .  إن شئت رفعت ،  وإن شئت نصبت .  وقد نصب حمزة ورفع الكسائي .  قال الفراء :  وحدّثني إبراهيم بن محمد ابن أبى يحيى عن أبان بن أبى عياش عن أنس أن رسول الله صلى الله عليه وسلم قرأ :  ( والعين بِالعين ) رفعا .  قال الفرّاء :  فإذا رفعت العين أتبع الكلام العين ،  وإن نصبنه فجائز .  وقد كان بعضهم ينصب كله ،  فإذا انتهي إلى {  وَالْجُرُوحَ قِصَاصٌ } رفع .  وكل صواب ،  إِلا أن الرفع والنصب في عطوف إِنّ وأنّ إنما يسهلان إذا كان مع الأسماء أفاعيل ؛  مثل قوله {  وإذا قيل إن وعد اللّهِ حق والساعة لا ريب فِيها } كان النصب سهلا ؛  لأنّ بعد الساعة خبرها .  ومثله {  إن الأرض لِلّهِ يورِثها من يشاء مِن عبادِهِ والعاقِبة لِلمتقِين } ومثله {  وإِن الظالِمِين بعضُهم أولياء بعضٍ والله وَلِىُّ المتقِين } فإذا لم يكن بعد الاسم الثاني خبر رفعته ،  كقوله عزَّ وجلّ {  أنَّ الله برئ مِن المشرِكِين ورسوله } وكقوله {  فإن الله هو مولاه وجِبرِيل وصالِح المؤمِنين } وكذلك تقول :  إِنّ أخاك قائم وزيد ،  رفعت ( زيد ) بإتباعه الاسم المضمر في قائم .  فابنِ على هذا .

/خ69

وقوله :  {  وَآتَيْناهُ الإِنجِيلَ فِيهِ هُدًى .  .  .  }

ثم قال {  وَمُصَدِّقاً } فإن شئت جعل {  مُصَدِّقاً } من صفة عيسى ،  وإن شئت من صفة الإنجيل .

وقوله {  وَهُدًى وَمَوْعِظَةً لِّلْمُتَّقِينَ } متبع للمصدّق في نصبه ،  ولو رفعته على أن تتبعهما قوله {  فِيهِ هُدًى وَنُورٌ } كان صوابا .

وقوله :  {  وَقَالَتِ الْيَهُودُ يَدُ اللَّهِ مَغْلُولَةٌ .  .  .  }

أرادوا :  ممسكة عن الإنفاق والإسباغ علينا .  وهو كقوله {  ولا تجعلْ يَدَكَ مَغْلُولَةً إِلى عُنُقك ولا تَبْسُطْها كلَّ البَسْطِ } في الإنفاق .

{  بَلْ يَدَاهُ مَبْسُوطَتَانِ } وفي حرف  عبد الله {  بل يداه بُِسْطَان } والعرب تقول :  الق أخاك بوجه مبسوط ،  وبوجه بُِسْط .

وقوله :  {  فَصِيَامُ ثَلاَثَةِ أَيَّامٍ .  .  .  }

في حرف عبد الله  " ثلاثة أيام متتابعات "  ولو نوّنت في الصيام نصبت الثلاثة ؛  كما قال الله تبارك وتعالى :  {  أو إِطعامٌ في يومٍ ذِي مَسْغَبةٍ يتيما } نصبت ( يتيما ) بإيقاع الإطعام عليه .  ومثله قوله :  {  أَلَمْ نجعلِ الأرض كِفَاتاً أحياء وأمواتا } ،  تكْفِتُهم أحياء وأمواتا .  وكذلك قوله {  فجزاء مِثلُ ما قتل من النعم } ولو نصبت ( مثل ) كانت صوابا .  وهي في قراءة عبد الله  " فجزاؤه مثل ما قتل "  ،  وقرأها بعض أهل المدينة  " فجزاء مِثلِ ما قَتَل "  ،  وكلُّ ذلك صواب .

وأما قوله {  ولا نَكْتُم شهادةَ اللّهِ } لو نوّنت في الشهادة ،  جاز النصب في إعراب ( اللّه ) على :  ولا نكتم اللّهَ شهادةً .  وأما من استفهم بالله ،  فقال ( اللّهِ ) فإنما يخفض ( اللّهِ ) في الإعراب كما يخفض القسم ،  لا على إضافة الشهادة إليه .

قوله :  {  فَجَزَاء مثْلُ ما قَتَلَ مِنَ النَّعَمِ يَحْكُمُ بِهِ ذَوَا عَدْلٍ مِّنْكُمْ .  .  .  }

يقول :  من أصاب صيدا ناسيا لإحرامه ،  معتمِدا للصيد ،  حكم عليه حاكِمان عدلان فقيهان يسألانه :  أقتلت قبل هذا صيدا ؟  فإن قال :  نعم ،  لم يحكما عليه ،  وقالا :  ينتقم الله منك .  وإن قال :  لا ،  حكما عليه ،  فإن بلغ قيمةُ حكمها ثمن بَدَنة أو شاة ،  حكما بذلك عليه {  هَدْياً بَالِغَ الْكَعْبَةِ } ،  وإن لم يبلغ ثمن شاة حكما عليه بقيمة ما أصاب :  دراهم ،  ثمّ قوّماه طعاما ،  وأطعمه المساكين ،  لكل مسكين نصفُ صاع .  فإن لم يجد ،  حَكَما عليه أن يصوم يوما مكان كل نصف صاع .

وقوله :  {  أَو عَدْلُ ذلك صِيَاما } والعَدْل :  ما عادل الشيء من غير جنسه ،  والعِدل الْمِثل .  وذلك أن تقول :  عندي عِدل غلامك ،  وعِدل شاتك ،  إذا كان غلاما يعدل غلاما أو شاة تعدل شاة .  فإذا أردت قيمته ،  من غير جنسه نصبت العين .  وربما قال بعض العرب :  عِدله .  وكأنه منهم غلط لتقارب معنى العَدْل من العِدل .  وقد اجتمعوا على واحد الأعدال أنه عِدل .  ونصبك الصيام على التفسير ،  كما تقول :  عندي رطلان عسلا ،  ومِلء بيت قَتّا ،  وهو مما يفسّر للمبتدئ :  أن ينظر إلى ( مِن ) فإذا حسنت فيه ثم أُلقيت نصبت ؛  ألا ترى أنك تقول :  عليه عَدْل ذلك من الصيام .  وكذلك قول الله تبارك وتعالى {  فلَنْ يُقْبَل مِن أحَدِهِم مِلءُ الأرْضِ ذهبا } .

وقوله :  {  لاَ تَسْأَلُواْ عَنْ أَشْيَاء إِن تُبْدَ لَكُمْ تَسُؤْكُمْ .  .  .  }

خطب النبيّ صلى الله عليه وسلم الناس ،  وأخبرهم أن الله تبارك وتعالى قد فرض عليهم الحّج ،  فقام رجل فقال :  يا رسول الله ( أَوَ في ) كلّ عام فأعرض عنه .  ثم عاد ( فقال :  أفي كل عام ،  فأعرض عنه ،  ثم عاد ) فقال له النبي صلى الله عليه وسلم :   " ما يؤمنك أن أقول ( نعم ) فيجب عليكم ،  ثم لا تفعلوا فتكفروا .  اتركوني ما تركتكم "  .

و( أشياء ) في موضع خفض لا تُجْرَى .  وقد قال فيها بعض النحويين :  إنما كثرت في الكلام ،  وهي ( أفعال ) فأشبهت فَعْلاء فلم تُصرف ؛  كما لم تصرف حمراء ،  وجمعها أشاوَى - كما جمعوا عذراء عذارَى ،  وصحراء صحارى - وأشياوات ؛  كما قيل :  حمراوات .  ولو كانت على التوهّم لكان أملك الوجهين بها أن تُجْرَى ؛  لأن الحرف إذا كثر به الكلام خَفّ ؛  كما كثرت التسمية بيزيد ،  فأجَروه ،  وفيه ياء زائدة تمنع من الإجراء .  ولكنا نرى أن أشياء جُمعت على أفعِلاء ،  كما جمع لَيِّن وأَلْيِناء ،  فحذف من وسط أشياء همزة ،  كان ينبغي لها أن تكون ( أَشْيِئاء ) فحذفت الهمزة لكثرتها .  وقد قالت العرب :  هذا من أبناوات سعد ،  وأُعيذك بأسماوات الله ،  وواحدها أسماء وأبناء تجرى ،  فلو مَنعت أشياء الجَرْي لجمعهم إياها أشياوات لم أُجر أسماء ولا أبناء ؛  لأنهما جُمِعتا أسماوات وأبناوات .

وقوله :  {  ما جَعَلَ اللَّهُ مِن بَحِيرَةٍ وَلاَ سَائبَةٍ وَلاَ وَصِيلَةٍ وَلاَ حامٍ .  .  .  }

قد اختُلِف في السائبة .  فقيل :  كان الرجل يُسيِّب من ماله ما شاء ،  يذهب به إلى الذين يقومون على خدمة آلهتهم .  قال بعضهم :  السائبة إذا ولدت الناقة عشرة أبطن كلهنّ إناث سُيِّبت ،  فلم تُركَب ولم يُجَزَّ لها وَبَر ،  ولم يَشرب لبنَها إلا ولدُها أو ضيفٌ حتى تموت .  فإذا ماتت أكلها الرجالُ والنساءُ ،  وبُحِرت أذنُ ابن ابنتها - يريد :  خُرِقت - فالبَحِيرة ابنة السائبة ،  وهي بمنزلة أمّها .  وأما الوصيلة فمن الشاء .  إذا ولدت الشاة سبعة أبطن عَناقين عَناقين ،  فولدت في سابعها عَناقا وَجْديا ،  قيل :  وصلت أخاها ،  فلا يشرب لبنَها النساءُ ،  وكان للرجال ،  وجرت مجرى السائبة .  وأما الحامي فالفحل من الإبل ؛  كان إذا لَقِح ولدُ ولده حَمَى ظهره ،  فلا يُركب ولا يُجزّ له وَبَر ،  ولا يُمنع من مرعىً ،  وأي إبل ضَرب فيها لم يُمنع .

فقال الله تبارك وتعالى {  ما جَعَلَ اللَّهُ مِن بَحِيرَةٍ } هذا أنتم جعلتموه كذلك .  قال الله تبارك وتعالى {  وَلَكِنَّ الَّذِينَ كَفَرُواْ يَفْتَرُونَ على اللَّهِ الْكَذِبَ وَأَكْثَرُهُمْ لاَ يَعْقِلُونَ } .

وقوله :  {  إِذْ أَيَّدتُّكَ .  .  .  }

على فعَّلتُك ؛  كما تقول :  قوَّيتُك .  وقرأ مجاهد ( آيدْتُك ) على أَفعلْتُك .  وقال الكسائي :  فاعلتُك ،  وهي تجوز .  وفي مثل عاونتُك .

وقوله :  {  فِي الْمَهْدِ } يقول :  صبِيّا ،  {  وَكَهْلاً } فردّ الكهل على الصفة ،  كقوله {  دعانا لجنبِهِ أَو قاعِدا أَو قائما } .

وقوله :  {  وَإِذْ أَوْحَيْتُ إِلَى الْحَوَارِيِّينَ أَنْ آمِنُواْ بِي وَبِرَسُولِي .  .  .  }

يقول :  ألهمتهم ،  كما قال {  وأَوحى ربُّك إِلى النحلِ أَنِ اتخِذِي مِن الجبال بيوتا } أي ألهمَها .

{  إِذْ قَالَ الْحَوَارِيُّونَ يا عِيسَى ابْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنا مائدَةً مِّنَ السَّماء قَالَ اتَّقُواْ اللَّهَ إِن كُنْتُم مُّؤْمِنِينَ } .

وقوله :  {  يا عِيسَى ابْنَ مَرْيَمَ .  .  .  }

( عيسى ) في موضع رفع ،  وإن شئت نصبت .  وأما ( ابن ) فلا يجوز فيه إلا النصب .  وكذلك تفعل في كل اسم دعوته باسمه ونسبته إلى أبيه ،  كقولك :  يا زيدُ بنَ  عبد الله ،  ويا زيدَ بنَ  عبد الله .  والنصب في ( زيد ) في كلام العرب أكثر .  فإذا رفعت فالكلام على دعوتين ،  وإذا نصبت فهو دعوة .  فإذا قلت :  يا زيدُ أخا تميم ،  أو قلت :  يا زيدُ ابن الرجلِ الصالح رفعت الأوّل ،  ونصبت الثاني ،  كقول الشاعر :

   يا زِبْرِقانُ أخا بنى خَلَفٍ *** ما أنتَ ويلَ أبيك والفَخْرُ
